#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    std::string html;
    std::stringstream ss(markdown);

    // Convert the markdown to HTML
    std::string line;
    while (std::getline(ss, line)) {
        html += line + "\n";
    }

    return html;
}

int main() {
    std::string markdownHtml = markdownToHtml("Hello, World!");
    std::cout << "Markdown: " << markdownHtml << std::endl;
    std::cout << "HTML: " << markdownHtml << std::endl;
    return 0;
}
```

